const DAYS=[{"day": 1, "week": 0, "coding": "Python baseline + Two Sum", "code": "https://www.hellointerview.com/learn/code/two-pointers/two-sum", "chapters": [{"n": 1, "title": "How to use a laboratory textbook", "page": 5}, {"n": 2, "title": "The mathematical machinery of learning", "page": 8}], "design": "https://www.hellointerview.com/learn/system-design/in-a-hurry/delivery", "label": "Delivery framework", "evidence": "Run lesson_01.py. Record one parameter you changed, your prediction and the observed result. Explain how this lesson connects to NoteEchoes, and name one failure to test.", "beginner": [{"n": 1, "title": "A small app, a clear goal, and a new way to learn"}], "local_ai": "What you actually download when you download a model. You have run local models already. Understanding the package lets you tell which change could alter its behavior. A model is a numerical function; a runtime is the program that executes it.", "resume_defense": {"project": "NoteEchoes (On-Device)", "topic": "Application Sandboxing vs Model Proposing", "q": "In NoteEchoes, how did you ensure the on-device model doesn't execute unauthorized phone actions?", "points": ["The LLM (Qwen 0.6B) is strictly an intent-and-argument proposer; it has zero direct access to iOS EventKit or calendar APIs.", "Swift application layer parses the proposed JSON into a strongly-typed envelope, validates date/time ranges, and checks iOS permissions.", "If intent confidence is < 0.75 or destructive actions are proposed, the application enforces a native UI confirmation modal before committing."]}}, {"day": 2, "week": 0, "coding": "3-Sum + complexity", "code": "https://www.hellointerview.com/learn/code/two-pointers/3-sum", "chapters": [{"n": 3, "title": "Build a differentiation engine you can inspect", "page": 15}], "design": "https://www.hellointerview.com/learn/system-design/core-concepts/api-design", "label": "API design", "evidence": "Run lesson_02.py. Record one parameter you changed, your prediction and the observed result. Explain how this lesson connects to NoteEchoes, and name one failure to test.", "beginner": [{"n": 2, "title": "Numbers, vectors and matrices without the mystery"}], "local_ai": "Parameters, tensors and the memory budget. A model name such as 7B tells you how many learned numbers it contains, not how much total RAM a running application will consume.", "resume_defense": {"project": "Edge vs Cloud (UMA vs PCIe)", "topic": "Unified Memory Architecture vs Cloud Server Buses", "q": "How does memory transfer differ between running NoteEchoes on an iPhone vs serving LLaMA-3 at Bank of America?", "points": ["On Apple Silicon (iPhone/Mac), CPU, GPU, and ANE share physical LPDDR5 RAM via Unified Memory Architecture (UMA) with zero PCIe copy overhead.", "On Azure cloud servers (A100/H100), tensors must transfer across PCIe Gen4/Gen5 buses (32-64 GB/s) unless using NVLink (600-900 GB/s) between GPUs.", "For mobile B=1 inference, unified zero-copy memory is the difference between sub-400ms latency and unacceptable UI freezing."]}}, {"day": 3, "week": 0, "coding": "Sliding window: cold revision", "code": "https://www.hellointerview.com/learn/code/sliding-window/longest-substring-without-repeating-characters", "chapters": [{"n": 4, "title": "From a table of counts to a language model", "page": 20}, {"n": 5, "title": "Tokenization and the language-model objective", "page": 24}], "design": "https://www.hellointerview.com/learn/system-design/core-concepts/data-modeling", "label": "Data modeling", "evidence": "Run lesson_03.py. Record one parameter you changed, your prediction and the observed result. Explain how this lesson connects to NoteEchoes, and name one failure to test.", "beginner": [{"n": 3, "title": "Scores become probabilities: softmax and temperature"}], "local_ai": "Storage precision is different from sampling temperature. Both quantization and temperature can change the words you see. They act at different stages, so confusing them makes experiments hard to interpret.", "resume_defense": {"project": "NoteEchoes (On-Device)", "topic": "Softmax Confidence Thresholding & Battery Conservation", "q": "Why is Softmax temperature and thresholding critical for on-device battery life?", "points": ["At temperature 0 (greedy decoding), we get deterministic intent classification without wasting compute sampling rare tokens.", "We apply a Softmax probability cutoff (0.75): ambiguous voice transcripts drop below this threshold and exit the generation loop immediately.", "Early exit saves up to 80 output token generation cycles, directly conserving GPU watt-hours and preventing device warming."]}}, {"day": 4, "week": 0, "coding": "Intervals: cold revision", "code": "https://www.hellointerview.com/learn/code/intervals/merge-intervals", "chapters": [{"n": 6, "title": "Attention, derived from the information problem", "page": 29}], "design": "https://www.hellointerview.com/learn/system-design/core-concepts/caching", "label": "Caching", "evidence": "Run lesson_04.py. Record one parameter you changed, your prediction and the observed result. Explain how this lesson connects to NoteEchoes, and name one failure to test.", "beginner": [{"n": 4, "title": "Build your first language predictor with counts"}], "local_ai": "What 4-bit and 8-bit quantization really mean. Quantization lets you store weights with fewer bits. To understand its tradeoff, follow one weight through compression and reconstruction.", "resume_defense": {"project": "NoteEchoes (On-Device)", "topic": "Model Footprint: Small Neural Model vs Static N-Grams", "q": "Why deploy a 0.6B fine-tuned neural model instead of a fast rule-based regex or n-gram classifier on mobile?", "points": ["An n-gram dictionary scales exponentially with vocabulary and fails completely on natural speech variations, colloquialisms, and speech recognition typos.", "Qwen 0.6B INT8 compresses semantic understanding into 649MB, generalizing across phrasing ('remind me tomorrow', 'ping me in 24h', 'alert me Friday').", "We evaluate on a 600-case challenge set containing speech noise; the neural model maintains 100% operational intent accuracy while n-grams score under 40%."]}}, {"day": 5, "week": 0, "coding": "Top K with a heap", "code": "https://www.hellointerview.com/learn/code/heap/kth-largest-element-in-an-array", "chapters": [{"n": 7, "title": "Assemble, train and debug a transformer", "page": 35}, {"n": 8, "title": "Training data, targets, and the optimizer contract", "page": 40}], "design": "https://www.hellointerview.com/learn/system-design/core-concepts/db-indexing", "label": "Database indexing", "evidence": "Run lesson_05.py. Record one parameter you changed, your prediction and the observed result. Explain how this lesson connects to NoteEchoes, and name one failure to test.", "beginner": [{"n": 5, "title": "Turn text into tokens, then into embeddings"}], "local_ai": "Group size, scales and quantization overhead. A single unusually large weight can force a coarse scale for many small weights. Grouping lets different portions of a matrix use different ranges.", "resume_defense": {"project": "Edge vs Cloud", "topic": "Tokenizer RAM Overhead & Chat Template Envelopes", "q": "How do tokenizers impact latency on mobile compared to cloud serving?", "points": ["Qwen uses a 151,936-token vocabulary. In INT8, the embedding matrix alone consumes ~155MB in Unified Memory.", "On mobile, long system prompts burn precious context and decode latency; we designed a compact 45-token CoreV5 prompt contract.", "In cloud vLLM at Bank of America, tokenizers run asynchronously on the host CPU worker pool, decoupled from GPU execution queues."]}}, {"day": 6, "week": 0, "coding": "Binary search boundaries", "code": "https://www.hellointerview.com/learn/code/binary-search/search-in-rotated-sorted-array", "chapters": [{"n": 9, "title": "Read a decoder implementation from input to sample", "page": 44}], "design": "https://www.hellointerview.com/learn/system-design/problem-breakdowns/distributed-rate-limiter", "label": "Rate limiter", "evidence": "Run lesson_06.py. Record one parameter you changed, your prediction and the observed result. Explain how this lesson connects to NoteEchoes, and name one failure to test.", "beginner": [{"n": 6, "title": "Loss and gradients: teach one number to improve"}], "local_ai": "What changes when you fine-tune a local model. Inference uses learned weights to make a prediction. Fine-tuning uses examples and an error signal to change selected learned values. This connects your local projects to today's gradient lesson.", "resume_defense": {"project": "NoteEchoes (On-Device)", "topic": "Why We Train Off-Device (Backprop Activation Caching)", "q": "Why didn't you train or fine-tune NoteEchoes directly on the user's iPhone?", "points": ["Forward inference only stores static weights (649MB) and incremental KV cache (~112MB for 1k tokens).", "Backpropagation requires saving all intermediate activation matrices across all 28 layers for gradient calculation, consuming ~3x the memory of inference (>2.5GB).", "iOS limits foreground app memory to ~1.5GB-2GB; backprop triggers an immediate OS jetsam memory termination. We train QLoRA on Mac/Cloud and ship inference-only."]}}, {"day": 7, "week": 0, "coding": "Week 1 mixed coding mock", "code": "https://www.hellointerview.com/learn/code", "chapters": [{"n": 10, "title": "Position, rotary geometry, and the KV cache", "page": 49}, {"n": 12, "title": "Inference, decoding and context limits", "page": 57}], "design": "https://www.hellointerview.com/learn/system-design/in-a-hurry/delivery", "label": "45-minute design rehearsal", "evidence": "Run lesson_07.py. Record one parameter you changed, your prediction and the observed result. Explain how this lesson connects to NoteEchoes, and name one failure to test.", "beginner": [{"n": 7, "title": "The training loop, batches and honest evaluation"}], "local_ai": "Fine-tuning examples, targets and validation splits. A training run can learn formatting mistakes or memorize examples. Good data defines the behavior you want and gives you an honest way to check improvement.", "resume_defense": {"project": "Bank of America (Enterprise Cloud)", "topic": "Single-Stream Decoding (B=1) vs Cloud Continuous Batching", "q": "Explain the architectural difference between serving NoteEchoes on mobile vs LLaMA-3 on Azure via vLLM.", "points": ["Mobile inference is single-stream (batch size B=1) and strictly memory-bandwidth bound: each token requires streaming all 649MB of weights through memory.", "At Bank of America, vLLM uses iteration-level continuous batching, grouping 32+ requests per forward pass to saturate GPU tensor cores (compute-bound).", "While mobile optimizes for Time-To-First-Token (TTFT < 200ms) for one user, enterprise vLLM optimizes for aggregate throughput (tokens/sec/dollar)."]}}, {"day": 8, "week": 1, "coding": "DFS: tree recursion", "code": "https://www.hellointerview.com/learn/code/depth-first-search/validate-binary-search-tree", "chapters": [{"n": 15, "title": "Prompting and in-context learning", "page": 66}, {"n": 16, "title": "Context engineering and constrained output", "page": 70}], "design": "https://www.hellointerview.com/learn/system-design/patterns/realtime-updates", "label": "Streaming updates", "evidence": "Run lesson_08.py. Record one parameter you changed, your prediction and the observed result. Explain how this lesson connects to NoteEchoes, and name one failure to test.", "beginner": [{"n": 8, "title": "Neural networks and autograd, one layer at a time"}], "local_ai": "MLX lazy evaluation and automatic differentiation. MLX code can describe calculations before executing them. This affects both how gradients are produced and how you time a computation.", "resume_defense": {"project": "NoteEchoes (On-Device)", "topic": "Heterogeneous Compute: Apple Neural Engine (ANE) vs GPU", "q": "How did you partition the multimodal speech-to-action pipeline across Apple Silicon hardware?", "points": ["Audio speech-to-text (Whisper) uses a fixed-shape encoder-decoder graph compiled to the Apple Neural Engine (ANE), drawing only 1-2W of power.", "Dynamic autoregressive text decoding (Qwen 0.6B) dispatches to the Apple Silicon GPU via MLX, utilizing unified memory shared buffers.", "Application validation and iOS EventKit reminders run on the CPU. This heterogeneous split avoids GPU thermal throttling."]}}, {"day": 9, "week": 1, "coding": "DFS: connected components", "code": "https://www.hellointerview.com/learn/code/depth-first-search/number-of-islands", "chapters": [{"n": 17, "title": "Embeddings, similarity and vector databases", "page": 75}], "design": "https://www.hellointerview.com/learn/system-design/deep-dives/vector-databases", "label": "Vector databases", "evidence": "Run lesson_09.py. Record one parameter you changed, your prediction and the observed result. Explain how this lesson connects to NoteEchoes, and name one failure to test.", "beginner": [{"n": 9, "title": "Attention: let one word consult the others"}], "local_ai": "Apple Silicon unified memory and device execution. A local model must fit alongside your other applications. Shared physical memory reduces some transfers, but it does not remove the need to budget allocations.", "resume_defense": {"project": "Edge vs Cloud", "topic": "Self-Attention Scaling & Grouped Query Attention (GQA)", "q": "How does Grouped Query Attention (GQA) reduce memory in your resume models?", "points": ["Both LLaMA-3 (Bank of America) and Qwen (NoteEchoes) use Grouped Query Attention (GQA) with 16 query heads and 8 key/value heads.", "GQA shares key/value head representations across query head pairs, reducing KV cache memory by 50% compared to standard Multi-Head Attention (MHA).", "On mobile, this 50% reduction keeps KV cache under 115MB for 1,024 tokens, preserving room for other iOS app processes."]}}, {"day": 10, "week": 1, "coding": "BFS: queues and shortest steps", "code": "https://www.hellointerview.com/learn/code/breadth-first-search/rotting-oranges", "chapters": [{"n": 18, "title": "Build a retrieval pipeline, step by step", "page": 80}], "design": "https://www.hellointerview.com/learn/system-design/problem-breakdowns/fb-post-search", "label": "Search system", "evidence": "Run lesson_10.py. Record one parameter you changed, your prediction and the observed result. Explain how this lesson connects to NoteEchoes, and name one failure to test.", "beginner": [{"n": 10, "title": "Assemble a tiny transformer and follow one token"}], "local_ai": "Read the model configuration before guessing its shape. A model's parameter count does not tell you its layer count, hidden width or number of cache heads. Those determine different costs.", "resume_defense": {"project": "NoteEchoes (On-Device)", "topic": "Release Package Anatomy & Checkpoint Pinning", "q": "How was the NoteEchoes model packaged and verified before shipping to iOS?", "points": ["The release is pinned at commit b829d1d4 with SHA-256 checksums, packaging 28 transformer layers, 1024 hidden dim, and group-64 8-bit weights.", "Total bundle is 649MB (main weights file is 633MB). Model download is immutable and verified at launch in Swift before initialization.", "Integrity tests ensure the downloaded weights match the frozen 1,200-case evaluation manifest before the app accepts microphone input."]}}, {"day": 11, "week": 1, "coding": "Topological sort", "code": "https://www.hellointerview.com/learn/code/graphs/course-schedule", "chapters": [{"n": 19, "title": "Grounded answering, knowledge graphs and GraphRAG", "page": 85}, {"n": 20, "title": "A retrieval experiment you can defend", "page": 88}], "design": "https://www.hellointerview.com/learn/system-design/problem-breakdowns/web-crawler", "label": "Ingestion and deduplication", "evidence": "Run lesson_11.py. Record one parameter you changed, your prediction and the observed result. Explain how this lesson connects to NoteEchoes, and name one failure to test.", "beginner": [{"n": 11, "title": "Position, context limits and the KV cache"}], "local_ai": "KV cache: why long conversations consume more memory. During generation, the model repeatedly consults earlier tokens. Caching their keys and values avoids recomputing them, but memory grows with the stored context.", "resume_defense": {"project": "Edge vs Cloud", "topic": "KV Cache Memory Calculations on the Whiteboard", "q": "Calculate the exact KV cache memory footprint for your model on the whiteboard.", "points": ["Formula: RAM = 2 (keys+values) × L (layers) × H_kv (KV heads) × D_h (head dimension) × T (tokens) × 2 bytes (FP16).", "For NoteEchoes (L=28, H_kv=8, D_h=128): 2 × 28 × 8 × 128 × 2 = 114,688 bytes (~112 KB) per token. For 1,024 tokens, KV RAM = 114.6 MB.", "For Bank of America LLaMA-3 8B (L=32, H_kv=8, D_h=128): 2 × 32 × 8 × 128 × 2 = 131,072 bytes (128 KB) per token. For 4k tokens = 512 MB per stream."]}}, {"day": 12, "week": 1, "coding": "Stack: parsing", "code": "https://www.hellointerview.com/learn/code/stack/decode-string", "chapters": [{"n": 21, "title": "Numerical case study: search quality is not answer quality", "page": 90}, {"n": 22, "title": "Build an evidence service from explicit boundaries", "page": 93}], "design": "https://www.hellointerview.com/learn/system-design/patterns/long-running-tasks", "label": "Long-running processing", "evidence": "Run lesson_12.py. Record one parameter you changed, your prediction and the observed result. Explain how this lesson connects to NoteEchoes, and name one failure to test.", "beginner": [{"n": 12, "title": "Choose output tokens and understand inference optimizations"}], "local_ai": "Prefill, decode and useful latency measurements. The delay before the first token and the speed of later tokens feel different to the user. One tokens-per-second number can hide that distinction.", "resume_defense": {"project": "NoteEchoes (On-Device)", "topic": "Memory Bandwidth Formula & Tokens/Second Limits", "q": "How do you calculate the maximum possible token generation speed on an iPhone?", "points": ["At batch size B=1, every token generated requires loading the entire model weights once from memory: Generation Speed = Memory Bandwidth / Model Weight.", "iPhone A17/A18 Pro has ~50 GB/s unified memory bandwidth. For our 649MB (0.65 GB) INT8 model: 50 GB/s / 0.65 GB ≈ 76.9 tokens/sec theoretical.", "In practice, with runtime overhead and thermal constraints, MLX delivers ~70-75 tokens/sec. A 7B model would drop to ~7 tokens/sec and overheat."]}}, {"day": 13, "week": 1, "coding": "Heap: merge sorted streams", "code": "https://www.hellointerview.com/learn/code/heap/merge-k-sorted-lists", "chapters": [{"n": 32, "title": "Build an evaluation that can change your mind", "page": 131}, {"n": 34, "title": "Design evaluations from the decision backward", "page": 137}], "design": "https://www.hellointerview.com/learn/system-design/problem-breakdowns/job-scheduler", "label": "Job scheduler", "evidence": "Run lesson_13.py. Record one parameter you changed, your prediction and the observed result. Explain how this lesson connects to NoteEchoes, and name one failure to test.", "beginner": [{"n": 13, "title": "Prompting, context and JSON that deserves checking"}], "local_ai": "Chat templates, special tokens and structured output. A fine-tuned model learned from a particular input format. A template mismatch can look like a weak model or a failed quantization even when neither is the cause.", "resume_defense": {"project": "Bank of America & NoteEchoes", "topic": "Constrained JSON Decoding & Schema Enforcement", "q": "How did you prevent malformed JSON outputs in your enterprise and mobile systems?", "points": ["In NoteEchoes, we implemented CoreV5 schema constraints; tokens that violate JSON syntax or enum fields are masked during decoding.", "At Bank of America, we enforced structured outputs with Pydantic and Outlines/vLLM guided decoding, ensuring 100% parseable extraction envelopes.", "Schema enforcement eliminates the need for expensive retry loops, saving up to 40% in processing latency across 10K+ monthly documents."]}}, {"day": 14, "week": 1, "coding": "Week 2 mixed coding mock", "code": "https://www.hellointerview.com/learn/code", "chapters": [{"n": 33, "title": "Read uncertainty without hiding behind a percentage", "page": 134}, {"n": 35, "title": "Statistics, online metrics and causal interpretation", "page": 141}], "design": "https://www.hellointerview.com/learn/system-design/in-a-hurry/delivery", "label": "RAG design mock", "evidence": "Run lesson_14.py. Record one parameter you changed, your prediction and the observed result. Explain how this lesson connects to NoteEchoes, and name one failure to test.", "beginner": [{"n": 14, "title": "Embeddings and search: find meaning without exact words"}], "local_ai": "Choose prompting, retrieval or fine-tuning by the failure. You have several ways to improve a local application. Each changes a different part of the system and solves a different kind of problem.", "resume_defense": {"project": "NoteEchoes (On-Device)", "topic": "On-Device Hybrid Retrieval (SQLite FTS5 + Local E5)", "q": "How does local note retrieval work in NoteEchoes without sending user data to the cloud?", "points": ["We built an on-device hybrid retrieval engine: SQLite FTS5 handles BM25 keyword matching, while a quantized E5 embedding model computes dense vectors.", "Exact keyword matches capture unique names ('Maya', 'Dentist'), while E5 cosine similarity captures semantic intent ('car service' matching 'mechanic').", "Results are combined using Reciprocal Rank Fusion (RRF) directly in SQLite/C++, running in under 25ms on device."]}}, {"day": 15, "week": 2, "coding": "Backtracking: subsets", "code": "https://www.hellointerview.com/learn/code/backtracking/subsets", "chapters": [{"n": 23, "title": "Tool calling is a contract, not an action", "page": 97}, {"n": 24, "title": "Agentic workflows, planning and state", "page": 102}], "design": "https://www.hellointerview.com/learn/system-design/patterns/multi-step-processes", "label": "Multi-step workflows", "evidence": "Run lesson_15.py. Record one parameter you changed, your prediction and the observed result. Explain how this lesson connects to NoteEchoes, and name one failure to test.", "beginner": [{"n": 15, "title": "Build RAG from a question and two documents"}], "local_ai": "Local embeddings: index memory and compatibility. A local retrieval system often needs an embedding model in addition to a generator. Its vectors and index consume memory and must remain compatible.", "resume_defense": {"project": "Bank of America (Enterprise Cloud)", "topic": "RAG Bottlenecks: Retrieval Recall@k vs Hallucination", "q": "At Bank of America, when document extraction hallucinated, how did you determine whether it was a retrieval or generation failure?", "points": ["We decoupled evaluation: first measured Retrieval Recall@k (is the supporting financial clause present in top-5 retrieved chunks?).", "If supporting text was absent (Recall@k = 0), it was a chunking/retrieval failure; prompting changes could not fix it.", "If supporting text was present but the extraction was wrong, we diagnosed generation faithfulness using TruLens Groundedness metrics."]}}, {"day": 16, "week": 2, "coding": "Backtracking: search", "code": "https://www.hellointerview.com/learn/code/backtracking/word-search", "chapters": [{"n": 25, "title": "Memory, context and durable execution", "page": 106}, {"n": 26, "title": "MCP, A2A and interoperability", "page": 110}], "design": "https://www.hellointerview.com/learn/system-design/core-concepts/api-design", "label": "Tool contracts", "evidence": "Run lesson_16.py. Record one parameter you changed, your prediction and the observed result. Explain how this lesson connects to NoteEchoes, and name one failure to test.", "beginner": [{"n": 16, "title": "Hybrid ranking and knowledge graphs without the hype"}], "local_ai": "Build a fair 16-bit, 8-bit and 4-bit comparison. A convincing comparison isolates precision. Otherwise a different prompt, model revision or generation limit may explain the outcome.", "resume_defense": {"project": "Bank of America (Enterprise Cloud)", "topic": "Reciprocal Rank Fusion (RRF) & Reranking Pipelines", "q": "How did you design hybrid search for complex enterprise document extraction?", "points": ["Lexical search (BM25) and dense vector search (Pinecone/Qdrant) produce non-comparable scores with different distributions.", "We implemented Reciprocal Rank Fusion: RRF Score = Σ 1 / (60 + Rank_i), prioritizing documents appearing near the top of both lists.", "We added a cross-encoder reranker (bge-reranker) on top-25 fused candidates, boosting extraction accuracy on messy tables by 35%."]}}, {"day": 17, "week": 2, "coding": "Linked-list pointers", "code": "https://www.hellointerview.com/learn/code/linked-list/remove-nth-node-from-end-of-list", "chapters": [{"n": 27, "title": "Human-in-the-loop and safe action design", "page": 114}, {"n": 28, "title": "Guardrails, AI security and prompt-injection defense", "page": 117}], "design": "https://www.hellointerview.com/learn/system-design/in-a-hurry/core-concepts", "label": "Security and consistency", "evidence": "Run lesson_17.py. Record one parameter you changed, your prediction and the observed result. Explain how this lesson connects to NoteEchoes, and name one failure to test.", "beginner": [{"n": 17, "title": "Tools and human review: from a suggestion to an action"}], "local_ai": "Full fine-tuning versus LoRA. Updating every weight can require substantial memory. LoRA restricts the trainable change to a smaller factorized matrix while retaining the base model.", "resume_defense": {"project": "NoteEchoes (On-Device)", "topic": "Tool Calling Contract & Least Privilege Execution", "q": "In NoteEchoes, explain the contract between model tool proposals and system execution.", "points": ["Model outputs an envelope containing tool name (`reminders.propose`), arguments (`title`, `due_iso`), and certainty score.", "Application CoreActionV5Adapter validates arguments against system constraints (e.g. date cannot be in the past without explicit intent).", "The tool execution layer is sandbox-isolated: calendar APIs cannot execute arbitrary shell code or delete system files under any prompt instruction."]}}, {"day": 18, "week": 2, "coding": "Prefix sums + hash map", "code": "https://www.hellointerview.com/learn/code/prefix-sum/subarray-sum-equals-k", "chapters": [{"n": 29, "title": "Case study: survive a crash without inventing success", "page": 121}, {"n": 30, "title": "Implement a durable action workflow", "page": 124}, {"n": 31, "title": "Defend the boundary between information and authority", "page": 128}], "design": "https://www.hellointerview.com/learn/system-design/patterns/multi-step-processes", "label": "Retry and reconciliation", "evidence": "Run lesson_18.py. Record one parameter you changed, your prediction and the observed result. Explain how this lesson connects to NoteEchoes, and name one failure to test.", "beginner": [{"n": 18, "title": "Agents, memory and surviving a crash"}], "local_ai": "QLoRA and the frozen quantized base. LoRA reduces trainable state, but its frozen base can still be large. Quantizing that base reduces another major memory component.", "resume_defense": {"project": "NoteEchoes (On-Device)", "topic": "Mobile Agent State Resilience & App Backgrounding", "q": "How does NoteEchoes handle a user locking their phone mid-generation?", "points": ["iOS aggressively terminates background tasks after ~30 seconds of screen lock.", "We structured NoteEchoes as a durable 3-phase state machine: Audio Received → Intent Extracted → Confirmation Staged.", "State is persisted to local SQLite after each phase; if the app is terminated, it restores the staged confirmation card upon next launch without re-running audio."]}}, {"day": 19, "week": 2, "coding": "DP: define the state", "code": "https://www.hellointerview.com/learn/code/dynamic-programming/unique-paths", "chapters": [{"n": 42, "title": "Fine-tuning begins with a behavior gap", "page": 167}, {"n": 43, "title": "PEFT and the mechanics of LoRA", "page": 171}], "design": "https://www.hellointerview.com/learn/system-design/in-a-hurry/delivery", "label": "Adaptation design discussion", "evidence": "Run lesson_19.py. Record one parameter you changed, your prediction and the observed result. Explain how this lesson connects to NoteEchoes, and name one failure to test.", "beginner": [{"n": 19, "title": "Safety and prompt injection in plain language"}], "local_ai": "Why training can run out of memory when inference fits. Training must preserve information for backward computation and optimizer updates. A model that generates successfully may still exceed memory during fine-tuning.", "resume_defense": {"project": "Bank of America & NoteEchoes", "topic": "Prompt Injection Defense in Untrusted Data", "q": "How do you protect your systems when user notes or enterprise PDFs contain malicious prompt injections?", "points": ["Treat untrusted user data as passive strings, never concatenating it directly into system instruction blocks.", "Use XML/Markdown data demarcators (`<untrusted_document>` or `<user_note>`) with explicit model instructions to ignore instructions inside those tags.", "Hardened authorization: destructive actions (deleting calendar, issuing wire transfers) require deterministic application-level approval gates outside the model."]}}, {"day": 20, "week": 2, "coding": "DP: word segmentation", "code": "https://www.hellointerview.com/learn/code/dynamic-programming/word-break", "chapters": [{"n": 44, "title": "QLoRA, quantization and training efficiency", "page": 177}, {"n": 48, "title": "Numerical case study: the first LoRA update", "page": 193}], "design": "https://www.hellointerview.com/learn/system-design/deep-dives/redis", "label": "Serving cache", "evidence": "Run lesson_20.py. Record one parameter you changed, your prediction and the observed result. Explain how this lesson connects to NoteEchoes, and name one failure to test.", "beginner": [{"n": 20, "title": "MCP and A2A: understand the interface before the acronym"}], "local_ai": "Learning rate, rank, epochs and overfitting. Fine-tuning settings control different mechanisms. Raising all of them after a poor result gives you little explanation for what helped or harmed.", "resume_defense": {"project": "Edge vs Cloud", "topic": "Model Context Protocol (MCP) & Native Integration", "q": "Why standardize tool integrations using Model Context Protocol (MCP)?", "points": ["MCP standardizes how tools, resources, and prompts are exposed to language models over JSON-RPC, eliminating custom adapter glue code.", "On mobile, it allows NoteEchoes to plug into iOS Shortcuts, Reminders, and Notes seamlessly without changing model prompts.", "In enterprise cloud, MCP allows switching backend vector databases or API connectors without modifying model serving infrastructure."]}}, {"day": 21, "week": 2, "coding": "Week 3 mixed coding mock", "code": "https://www.hellointerview.com/learn/code", "chapters": [{"n": 45, "title": "Preference learning, alignment and distillation", "page": 181}, {"n": 50, "title": "Reasoning, reinforcement learning, and evidence of improvement", "page": 199}], "design": "https://www.hellointerview.com/learn/system-design/in-a-hurry/delivery", "label": "NoteEchoes deep dive", "evidence": "Run lesson_21.py. Record one parameter you changed, your prediction and the observed result. Explain how this lesson connects to NoteEchoes, and name one failure to test.", "beginner": [{"n": 21, "title": "Evaluation and statistics you can actually use"}], "local_ai": "Evaluate adaptation on tasks you actually care about. Loss measures token prediction, while your application needs usable outcomes. Evaluation connects training changes to user value.", "resume_defense": {"project": "Bank of America & NoteEchoes", "topic": "Evaluation Suites: Operational vs Strict Text Equality", "q": "Why did your NoteEchoes report show 100% operational accuracy but 91.4% strict text match?", "points": ["Strict text match requires output tokens to match ground truth character-for-character, penalizing semantically equivalent variations ('Tomorrow at 6pm' vs '6:00 PM tomorrow').", "Operational accuracy evaluates whether the parsed JSON produced the correct intent, correct ISO timestamp, and correct target calendar action.", "For production engineering, operational accuracy is what matters to users. We verify across 1,200 challenge rows (including noise and edge cases)."]}}, {"day": 22, "week": 3, "coding": "Greedy: invariant", "code": "https://www.hellointerview.com/learn/code/greedy/jump-game", "chapters": [{"n": 36, "title": "Model selection, routing and economic decisions", "page": 145}, {"n": 37, "title": "Serving internals: caches, batching, quantization and runtimes", "page": 149}], "design": "https://www.hellointerview.com/learn/system-design/problem-breakdowns/chatgpt", "label": "ChatGPT system design", "evidence": "Run lesson_22.py. Record one parameter you changed, your prediction and the observed result. Explain how this lesson connects to NoteEchoes, and name one failure to test.", "beginner": [{"n": 22, "title": "Serving, latency, cost and model routing"}], "local_ai": "MLX model loading, generation and benchmarking. A usable local workflow needs reproducible loading and inference before you add training. This becomes the baseline for every later comparison.", "resume_defense": {"project": "Bank of America (Enterprise Cloud)", "topic": "vLLM PagedAttention & Continuous Batching Deep-Dive", "q": "Explain PagedAttention to me like an operating systems architect.", "points": ["Standard LLM serving pre-allocates continuous virtual memory for each request's max context length, wasting up to 60-80% of GPU RAM on fragmentation.", "PagedAttention divides the KV cache into fixed-size physical memory blocks (like OS virtual memory pages), dynamically allocating blocks as tokens generate.", "This eliminates internal fragmentation, allows requests with shared prompt prefixes to share physical memory blocks, and boosts serving throughput by 2-4x."]}}, {"day": 23, "week": 3, "coding": "Matrix traversal", "code": "https://www.hellointerview.com/learn/code/matrices/set-matrix-zeroes", "chapters": [{"n": 38, "title": "Tracing, debugging and the production lifecycle", "page": 155}, {"n": 40, "title": "Numerical case study: capacity and quality together", "page": 160}, {"n": 41, "title": "Design a serving experiment before optimizing the server", "page": 163}], "design": "https://www.hellointerview.com/learn/system-design/problem-breakdowns/metrics-monitoring", "label": "Monitoring and capacity", "evidence": "Run lesson_23.py. Record one parameter you changed, your prediction and the observed result. Explain how this lesson connects to NoteEchoes, and name one failure to test.", "beginner": [{"n": 23, "title": "LLMOps, architecture and data engineering"}], "local_ai": "Merge, requantize and verify the served artifact. The artifact you deploy can differ numerically from the one you evaluated during training. A successful merge command is not proof of unchanged behavior.", "resume_defense": {"project": "NoteEchoes (On-Device)", "topic": "The Dequantized NF4 Base Merge Lesson", "q": "What happened when you merged your QLoRA adapter in NoteEchoes, and how did you resolve it?", "points": ["We trained an rsLoRA adapter on a 4-bit NF4 double-quantized base model. When merging into a standard FP16 base for MLX, subtle numerical shifts degraded intent boundary accuracy.", "The merged model began confusing 'clarify' and 'reminder' on edge cases, failing evaluation gates.", "Solution: We merged the adapter onto the dequantized NF4 double-quant base before converting to 8-bit MLX, perfectly matching training loss behavior."]}}, {"day": 24, "week": 3, "coding": "Practical Python: LRU + tests", "code": "https://www.hellointerview.com/learn/code/heap/overview", "chapters": [{"n": 39, "title": "AI application architecture and product integration", "page": 158}, {"n": 51, "title": "Data engineering is part of model engineering", "page": 202}], "design": "https://www.hellointerview.com/learn/system-design/deep-dives/postgres", "label": "PostgreSQL and SQL", "evidence": "Run lesson_24.py. Record one parameter you changed, your prediction and the observed result. Explain how this lesson connects to NoteEchoes, and name one failure to test.", "beginner": [{"n": 24, "title": "Fine-tuning, LoRA and QLoRA through your own adapter"}], "local_ai": "An MLX adapter training workflow you can explain. The main lesson derives LoRA. This companion turns that mechanism into a reproducible local experiment using your existing MLX experience.", "resume_defense": {"project": "Bank of America & NoteEchoes", "topic": "QLoRA Mechanics & Rank-Stabilized LoRA (rsLoRA)", "q": "Explain QLoRA and why you chose rank-stabilized LoRA (rsLoRA).", "points": ["QLoRA freezes base model weights in 4-bit NormalFloat (NF4) with double quantization, adding small trainable low-rank matrices A and B (rank 32).", "Standard LoRA scales updates by α/r. When increasing rank r to 32 or 64, standard LoRA scaling causes gradient instability and underfitting.", "Rank-stabilized LoRA (rsLoRA) scales by s = α / √r. For rank 32 and alpha 64: s = 64 / √32 ≈ 11.31, stabilizing gradient dynamics and boosting convergence."]}}, {"day": 25, "week": 3, "coding": "Practical Python: async worker", "code": "https://www.hellointerview.com/learn/code/graphs/topological-sort", "chapters": [{"n": 46, "title": "Multimodal representations and pipelines", "page": 185}, {"n": 49, "title": "Preserve evidence when inputs are images, audio, and video", "page": 196}], "design": "https://www.hellointerview.com/learn/system-design/patterns/long-running-tasks", "label": "Voice pipeline design", "evidence": "Run lesson_25.py. Record one parameter you changed, your prediction and the observed result. Explain how this lesson connects to NoteEchoes, and name one failure to test.", "beginner": [{"n": 25, "title": "Preferences, reinforcement learning and distillation"}], "local_ai": "Distillation and preference learning for smaller models. After supervised fine-tuning, a model may still choose poor responses or be too expensive. Preference learning and distillation address different aspects of that problem.", "resume_defense": {"project": "Bank of America (Enterprise Cloud)", "topic": "Enterprise Evaluation: Ragas, TruLens, and ROUGE/BLEU", "q": "How did you set up Ragas and TruLens at Bank of America to measure hallucination?", "points": ["We implemented the TruLens RAG Triad: Context Relevance (retriever), Groundedness (faithfulness of answer to retrieved docs), and Answer Relevance (to query).", "We tracked Faithfulness scores: if Faithfulness dropped below 0.90, the pipeline routed to human review rather than automatic document ingestion.", "For structured text extraction, we combined ROUGE-1/2/L and BLEU with schema validity checks to guarantee compliance across 10K+ monthly documents."]}}, {"day": 26, "week": 3, "coding": "Trie or weakest pattern", "code": "https://www.hellointerview.com/learn/code/trie/overview", "chapters": [{"n": 11, "title": "Efficient attention, experts, and speculative decoding", "page": 53}, {"n": 47, "title": "Advanced systems and a complete learning capstone", "page": 190}], "design": "https://www.hellointerview.com/learn/system-design/problem-breakdowns/distributed-cache", "label": "Distributed cache", "evidence": "Run lesson_26.py. Record one parameter you changed, your prediction and the observed result. Explain how this lesson connects to NoteEchoes, and name one failure to test.", "beginner": [{"n": 26, "title": "Multimodal AI and the complete NoteEchoes journey"}], "local_ai": "Audio pipelines: find which model made the mistake. A voice application includes several transformations. Fine-tuning the language model cannot reliably repair a fact that was lost before it received the transcript.", "resume_defense": {"project": "Bank of America (Enterprise Cloud)", "topic": "vLLM Chunked Prefill & TTFT vs TPOT Optimization", "q": "How do you balance Time-To-First-Token (TTFT) and Time-Per-Output-Token (TPOT) under heavy load?", "points": ["Prefill (processing prompt tokens) is compute-heavy; decode (generating new tokens) is memory-bandwidth bound.", "A sudden 8,000-token prompt prefill will pause ongoing token generation for all active users, creating a huge spike in TPOT (jitter).", "We enabled vLLM Chunked Prefill: chunking prompt prefills into 512-token batches co-scheduled with ongoing decode steps, flattening P99 latency."]}}, {"day": 27, "week": 3, "coding": "Unseen timed coding problem", "code": "https://www.hellointerview.com/learn/code", "chapters": [{"n": 52, "title": "Demonstrate depth in interviews and choose a specialization", "page": 205}, {"n": 53, "title": "The capstone: a document assistant you can defend", "page": 209}], "design": "https://www.hellointerview.com/learn/system-design/in-a-hurry/delivery", "label": "Complete AI design mock", "evidence": "Run lesson_27.py. Record one parameter you changed, your prediction and the observed result. Explain how this lesson connects to NoteEchoes, and name one failure to test.", "beginner": [{"n": 27, "title": "Coding, SQL, system design and behavioral interviews"}], "local_ai": "Benchmark local models without misleading yourself. Short tests can miss loading costs, thermal changes and variance. A useful report explains the workload and conditions behind each number.", "resume_defense": {"project": "Resume Defense Masterclass", "topic": "How to Defend the 40% Extraction Efficiency Metric", "q": "Defend the 'improved document extraction efficiency by 40%' bullet on your resume.", "points": ["Baseline: Legacy OCR + rule-based extraction took ~4.2 seconds per multi-page document with a 22% manual review rate due to missed table cells.", "Intervention: Fine-tuned LLaMA-3 QLoRA served via vLLM with PagedAttention and hybrid RAG, reducing average latency to 2.5s and cutting manual review by 60%.", "Metric Calculation: (4.2s - 2.5s) / 4.2s = 40.5% latency reduction, plus a measured 40% reduction in human-in-the-loop audit hours."]}}, {"day": 28, "week": 3, "coding": "Mock loop A", "code": "https://www.hellointerview.com/learn/code", "chapters": [{"n": 13, "title": "Consolidation: make the concepts yours", "page": 61}, {"n": 14, "title": "Numerical case study: one forward pass and its loss", "page": 63}], "design": "https://www.hellointerview.com/learn/system-design/problem-breakdowns/chatgpt", "label": "AI system-design mock", "evidence": "Run lesson_28.py. Record one parameter you changed, your prediction and the observed result. Explain how this lesson connects to NoteEchoes, and name one failure to test.", "beginner": [{"n": 28, "title": "Your capstone and a learning plan that allows understanding"}], "local_ai": "Choose a model by its quality–memory–latency tradeoff. The smallest artifact is not always the best application choice, and the largest model is not always worth its cost. Selection needs explicit constraints.", "resume_defense": {"project": "Edge vs Cloud (Hybrid Architecture)", "topic": "Hybrid Edge-Cloud Routing Architecture", "q": "When does NoteEchoes execute on device, and when would it escalate to the cloud?", "points": ["Local Fast Path: Voice notes, personal reminders, on-device search run 100% locally on iPhone (<400ms, zero API cost, full privacy).", "Cloud Escalation Path: Multi-document financial analysis or web search is routed to cloud vLLM if the intent classifier detects high token complexity.", "User Control: Hybrid routing is transparent; sensitive data never leaves the device without explicit toggle permissions."]}}, {"day": 29, "week": 4, "coding": "Repair your weakest two patterns", "code": "https://www.hellointerview.com/learn/code", "chapters": [{"n": 54, "title": "Laboratory setup and honest experiment boundaries", "page": 212}, {"n": 61, "title": "Twenty experiments: predictions, changes, and checks", "page": 238}], "design": "https://www.hellointerview.com/learn/system-design/in-a-hurry/delivery", "label": "Targeted design repair", "evidence": "Run lesson_29.py. Record one parameter you changed, your prediction and the observed result. Explain how this lesson connects to NoteEchoes, and name one failure to test.", "beginner": [{"n": 29, "title": "Your parameter map and a gentle glossary"}], "local_ai": "Debug local inference one stage at a time. A changed output has many possible causes. A controlled diagnosis prevents unnecessary retraining and helps you learn what each component does.", "resume_defense": {"project": "Bank of America & NoteEchoes", "topic": "Production Quantization: INT8 vs INT4 vs FP8", "q": "Compare INT8 (NoteEchoes), INT4 (AWQ), and FP8 (vLLM) for production.", "points": ["INT8 (group 64): Negligible perplexity loss (<0.1%), fast integer math on Apple Silicon GPU/ANE, 649MB footprint.", "INT4 (AWQ): Protects salient weight channels by analyzing activation magnitudes, saving 50% more RAM, ideal for 7B models on 8GB devices.", "FP8 (E4M3/E5M2): Native FP8 support depends on GPU generation and serving kernels; H100 supports FP8 Tensor Cores, while A100 does not provide the same native FP8 path. Measure accuracy and throughput on the actual deployment."]}}, {"day": 30, "week": 4, "coding": "Mock loop B + readiness review", "code": "https://www.hellointerview.com/learn/code", "chapters": [{"n": 52, "title": "Demonstrate depth in interviews and choose a specialization", "page": 205}], "design": "https://www.hellointerview.com/learn/system-design/in-a-hurry/delivery", "label": "Unfamiliar design prompt", "evidence": "Run tiny_decoder.py. Record one parameter you changed, your prediction and the observed result. Explain how this lesson connects to NoteEchoes, and name one failure to test.", "beginner": [{"n": 30, "title": "Optional workshop: read and run the complete tiny decoder"}], "local_ai": "Capstone: defend your own local model release. The goal is to explain the model you have used, not merely recognize terms. A small reproducible comparison makes the concepts concrete.", "resume_defense": {"project": "Resume Defense Capstone", "topic": "The 5-Minute Senior AI Engineer System Walkthrough", "q": "Walk me through your most technically challenging AI engineering architecture from end to end.", "points": ["Deliver the 4-layer walkthrough: (1) Ingestion & Pre-processing, (2) Model & Serving Architecture, (3) Guardrails & Validation, (4) Production Evaluation.", "Contrast NoteEchoes (on-device MLX, 649MB INT8, Apple Silicon UMA, sub-400ms) with Bank of America (Azure vLLM, PagedAttention, LLaMA-3, Ragas).", "End with trade-offs, quantifiable business metrics (40% efficiency boost, 1,200 challenge cases at 100% pass rate), and future improvements."]}}];const WEEKS=[["Build fluency", "Days 1\u20137", "Refresh Python and model mechanics; test your existing coding fluency.", "You already marked sliding windows and intervals complete in Arc. Re-test them cold, then spend saved time on weaker patterns."], ["Make RAG measurable", "Days 8\u201314", "Connect retrieval, ingestion, and evaluation to your enterprise and codebase work.", "Be ready to explain the 40% extraction-efficiency claim: metric, baseline, sample, time period, and personal contribution."], ["Defend agents and adaptation", "Days 15\u201321", "Practice state, authorization, LoRA, and feedback objectives.", "Your resume invites detailed questions about multi-agent loops, QLoRA, and NoteEchoes reinforcement learning. Distinguish shipped behavior from planned work."], ["Show production judgment", "Days 22\u201328", "Measure serving, explain on-device tradeoffs, and complete a mock loop.", "Use your Python, SQL, Spark, Azure, and backend experience as evidence; rehearse the decision and failure, not only the technology names."], ["Repair and rehearse", "Days 29\u201330", "Close the biggest gaps and assess interview readiness.", "Thirty days is a first pass. Use mock results to choose extra practice; a calendar does not guarantee readiness."]];
;

