// Keep reading controls aligned with the actual header and toolbar heights.
function updateReadingOffsets() {
  const headerHeight = isFocusMode ? 0 : $('.topbar').getBoundingClientRect().height;
  document.documentElement.style.setProperty('--study-header-height', `${headerHeight}px`);
  document.documentElement.style.setProperty('--study-toolbar-height', `${$('.bookbar').getBoundingClientRect().height}px`);
}
const readingLayoutObserver = new ResizeObserver(updateReadingOffsets);
readingLayoutObserver.observe($('.topbar'));
readingLayoutObserver.observe($('.bookbar'));

function setReadingFocus(enabled) {
  const toolbarBottom = $('.bookbar').getBoundingClientRect().bottom;
  const anchor = [...$('#reading').children].find(el => {
    const box = el.getBoundingClientRect();
    return box.height > 0 && box.bottom > toolbarBottom + 8 && box.top < innerHeight;
  });
  isFocusMode = enabled;
  $('.study-tools').open = false;
  document.body.classList.toggle('reading-focus', enabled);
  $('#workspace').classList.toggle('focus-mode', enabled);
  $('#focus-btn').classList.toggle('active', enabled);
  $('#focus-btn').setAttribute('aria-pressed', String(enabled));
  $('#focus-btn').innerHTML = enabled
    ? '<span class="focus-icon" aria-hidden="true">✕</span> Exit Focus'
    : '<span class="focus-icon" aria-hidden="true">▣</span> Focus';
  updateReadingOffsets();
  requestAnimationFrame(() => {
    (anchor || $('#workspace')).scrollIntoView({block:'start', behavior:'instant'});
  });
}
$('#focus-btn').onclick = () => setReadingFocus(!isFocusMode);
document.addEventListener('keydown', e => {
  if (e.key === 'Escape') {
    if (isFocusMode) setReadingFocus(false);
    $('.study-tools').open = false;
    $('.extra-views').open = false;
  }
});
document.addEventListener('click', e => {
  if (!e.target.closest('.study-tools')) $('.study-tools').open = false;
  if (e.target.closest('.study-tools .nav-pill, .study-tools #menu, .study-tools #job-audit-pill')) $('.study-tools').open = false;
});

// Sound Toggle
$('#sound-btn').onclick = () => {
  state.sound = !state.sound;
  $('#sound-icon').textContent = state.sound ? '🔊' : '🔇';
  toast(state.sound ? 'Sound effects enabled' : 'Sound effects muted');
  save();
};

// Achievements Modal
$('#achievements-btn').onclick = () => {
  renderAchievementsModal();
  $('#achievements-modal').showModal();
};
$('#close-achievements').onclick = () => $('#achievements-modal').close();
$('#achievements-modal').onclick = e => {
  if (e.target === $('#achievements-modal')) $('#achievements-modal').close();
};

// XP Pill Click -> Opens Achievements
$('#xp-pill').onclick = () => {
  renderAchievementsModal();
  $('#achievements-modal').showModal();
};

// Library Dialog
$('#menu').onclick = () => {
  $('#library').showModal();
  $('#menu').setAttribute('aria-expanded', 'true');
};
$('#close-menu').onclick = () => $('#library').close();
$('#library').addEventListener('close', () => {
  $('#menu').setAttribute('aria-expanded', 'false');
  $('#menu').focus();
});
$('#library').onclick = e => {
  if (e.target === $('#library')) $('#library').close();
};

// Export & Import Progress
$('#export').onclick = () => {
  const storage = {};
  for(const key of ['orbit.practice.v1','orbit-ai-depth-v1','orbit-ai-daily-v1','beginner-ai-practiced','llm-workshop-completed']) {
    const value=localStorage.getItem(key);if(value!==null)storage[key]=value;
  }
  const blob = new Blob([JSON.stringify({ ...state, version: 2, storage }, null, 2)], { type: 'application/json' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = 'orbit-ai-progress.json';
  a.click();
  setTimeout(() => URL.revokeObjectURL(url), 1000);
  $('#backup-status').textContent = 'Progress backup downloaded.';
};

$('#import').onchange = async e => {
  try {
    const backup = JSON.parse(await e.target.files[0].text());
    const data = backup.progress || backup;
    if (typeof data.days !== 'object' || !data.days) throw Error();
    const recovery={};
    const extraKeys=['orbit.practice.v1','orbit-ai-depth-v1','orbit-ai-daily-v1','beginner-ai-practiced','llm-workshop-completed'];
    for(const key of [KEY,...extraKeys])recovery[key]=localStorage.getItem(key);
    localStorage.setItem('orbit-before-dashboard-import-v1',JSON.stringify(recovery));
    state = {
      ...state, ...data,
      days: data.days,
      last: data.last || 1,
      streak: data.streak || { count: 1, lastDate: '' },
      achievements: data.achievements || {},
      sound: typeof data.sound === 'boolean' ? data.sound : true
    };
    for(const key of extraKeys)if(typeof backup.storage?.[key]==='string')localStorage.setItem(key,backup.storage[key]);
    if(backup.notes && typeof backup.notes==='object')localStorage.setItem('orbit-ai-depth-v1',JSON.stringify(backup.notes));
    save();
    show();
    $('#backup-status').textContent = 'Progress restored!';
  } catch (err) {
    $('#backup-status').textContent = 'Could not restore this file. Choose an Orbit progress JSON backup.';
  }
  e.target.value = '';
};

// Startup
window.addEventListener('hashchange', show);
initReadingScroll();
show();

;